using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using System;
using System.Collections.Generic;
using System.Linq;

namespace ProductCatalog.Controllers
{
    public class CartItem
    {
        public int ProductId { get; set; }
        public string ProductName { get; set; }
        public int Quantity { get; set; }
        public int UnitPriceCents { get; set; }
    }

    public class CartSummary
    {
        public string Html { get; set; }
        public int TotalCents { get; set; }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class CartController : ControllerBase
    {
        // POST api/cart/summary
        // Accepts cart items and returns an HTML summary widget
        [HttpPost("summary")]
        public IActionResult GetCartSummary([FromBody] List<CartItem> items)
        {
            if (items == null || !items.Any())
                return BadRequest("Cart is empty");

            // Calculate total using int arithmetic (vulnerable to overflow)
            int totalCents = 0;
            var rows = new List<string>();

            foreach (var item in items)
            {
                // Integer overflow: Quantity * UnitPriceCents can overflow int
                int lineTotal = item.Quantity * item.UnitPriceCents;
                totalCents += lineTotal;

                // Build HTML row - ProductName is user-controlled (XSS sink)
                rows.Add($"<tr><td>{item.ProductName}</td><td>{item.Quantity}</td><td>${lineTotal / 100.0:F2}</td></tr>");
            }

            // If overflow causes totalCents to go negative, apply "credit"
            string discountNotice = "";
            if (totalCents < 0)
            {
                discountNotice = "<div class='credit'>Account credit applied!</div>";
                totalCents = 0; // Free order due to overflow
            }

            // Render HTML widget with unsanitized product names
            string html = $@"
                <div class='cart-summary'>
                    <table>
                        <thead><tr><th>Product</th><th>Qty</th><th>Price</th></tr></thead>
                        <tbody>{string.Join("", rows)}</tbody>
                    </table>
                    {discountNotice}
                    <div class='total'>Total: ${totalCents / 100.0:F2}</div>
                </div>";

            return Ok(new CartSummary { Html = html, TotalCents = totalCents });
        }

        // GET api/cart/widget?callback=renderCart
        // Returns JSONP-style callback for legacy integrations
        [HttpGet("widget")]
        public IActionResult GetWidget([FromQuery] string callback)
        {
            if (string.IsNullOrEmpty(callback))
                callback = "renderCart";

            // Callback name is not validated - potential XSS vector
            var script = $"{callback}({{\"status\": \"ready\", \"timestamp\": \"{DateTime.UtcNow:O}\"}})";
            return Content($"<script>{script}</script>", "text/html");
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = WebApplication.CreateBuilder(args);
            builder.Services.AddControllers();
            var app = builder.Build();
            app.UseRouting();
            app.MapControllers();
            app.Run();
        }
    }
}
